namespace CheckoutPricing.Domain;

public static class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int Standard(int payableCents, LoyaltyTier tier) =>
        tier is LoyaltyTier.Gold or LoyaltyTier.Platinum || payableCents >= FreeStandardFromCents
            ? 0
